const PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#182449\">\n<meta name=\"description\" content=\"Discover independent products from India’s founders. Exchange thoughtful feedback and test demand for your next idea.\">\n<title>PitchAdda · Founder feedback exchange</title>\n<style>:root{color-scheme:light;--ink:#16213d;--muted:#546178;--blue:#304dcc;--line:#dbe0e8;--paper:#fafbf9}\n*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:1rem}body{margin:0;background:var(--paper);color:var(--ink);font:1rem/1.55 Inter,\"Helvetica Neue\",Arial,sans-serif;-webkit-font-smoothing:antialiased}\nbutton,input,textarea,select{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer;color:inherit}button:disabled{cursor:default;opacity:.65}a{color:var(--blue)}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #6179ff;outline-offset:4px}\n.wrap{width:min(1200px,91%);margin-inline:auto}.site-header{border-bottom:1px solid var(--line);background:#fff}.header-inner{display:flex;align-items:center;gap:3rem;min-height:74px}.brand{margin-right:auto;display:inline-flex;align-items:center;gap:10px;font-size:1.6rem;font-weight:800;letter-spacing:-1.6px;color:var(--ink);text-decoration:none}.brand-mark{background:#324fd0;border-radius:9px;width:32px;height:32px;display:flex;align-items:center;justify-content:center;gap:2px;transform:rotate(-5deg)}.brand-mark i{display:block;width:4px;height:12px;background:#fff;border-radius:1px;transform:skewY(-26deg)}.brand-mark i:first-child{height:8px}.brand-mark i:last-child{height:17px}\nnav{display:flex;gap:1.6rem}nav a{color:var(--muted);text-decoration:none;font-weight:600;font-size:.94rem}nav a[aria-current=page]{color:var(--blue)}button{border:0;border-radius:8px;font-weight:650;padding:.65rem 1rem;background:#eef1fa}.header-cta,.primary{background:var(--blue);color:#fff}.header-cta b{margin-right:4px}.header-cta:hover,.primary:hover{background:#223da8}\n.hero{position:relative;isolation:isolate;overflow:hidden;margin-top:26px;border-radius:22px;display:grid;grid-template-columns:1.08fr 1fr;align-items:center;background:radial-gradient(ellipse at 86% 58%,#2b4091 0%,transparent 58%),linear-gradient(112deg,#151e39,#1e2d65);color:#fff;padding:clamp(32px,4.2vw,64px);min-height:350px}.hero-copy{position:relative;z-index:1}.kicker{margin:0 0 1rem;display:flex;gap:10px;align-items:center;font-family:\"IBM Plex Mono\",ui-monospace,monospace;font-size:.78rem;font-weight:650;letter-spacing:.1em;color:#d2ddff}.kicker:before{content:\"\";width:19px;height:2px;background:#ffab7a}.hero h1,.dash h1{font:500 clamp(3.1rem,5.1vw,5rem)/1.02 Georgia,\"Times New Roman\",serif;letter-spacing:-.065em;margin:0}.hero h1 em{color:#ffbb8c;font-weight:400}.hero-copy>p:not(.kicker){max-width:37ch;margin:1.1rem 0 1.35rem;color:#e4e8f8;font-size:1.025rem}.hero-button{display:inline-flex;border-radius:8px;background:#fff;color:#1c2c54;font-size:.92rem;text-decoration:none;padding:.65rem 1.1rem;font-weight:700}.hero-button:hover{background:#edf1ff}.flight-scene{justify-self:center;margin-block:-38px}\n.progress{display:flex;align-items:center;gap:18px;padding:18px 22px;background:#fff;border:1px solid var(--line);border-radius:13px;margin:14px 0 36px}.progress-icon{width:36px;height:36px;display:grid;place-items:center;background:#edf0fe;border-radius:10px;color:#4059bd;font-size:1.25rem}.progress strong,.progress small{display:block}.progress strong{font-size:.98rem}.progress small{color:var(--muted);font-size:.875rem}.progress-end{margin-left:auto;display:flex;gap:12px;align-items:center;white-space:nowrap;font-size:.9rem;font-weight:700}.segments{display:flex;gap:4px}.segments i{display:block;width:30px;height:6px;border-radius:6px;background:#e4e7ef}.segments i.on{background:var(--blue)}\n.directory-head{display:flex;align-items:baseline;gap:1rem}.directory-head h2,.dialog-head h2{font:500 clamp(1.85rem,3vw,2.5rem)/1.15 Georgia,serif;letter-spacing:-.05em;margin:0}.directory-head span{font-size:.88rem;color:var(--muted)}.filters{display:flex;gap:7px;margin:18px 0;flex-wrap:wrap}.filters button{border-radius:22px;padding:.38rem .85rem;border:1px solid var(--line);background:#fff;font-size:.875rem;font-weight:600}.filters button[aria-pressed=true]{background:#202d4d;color:white;border-color:#202d4d}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n.card{border:1px solid var(--line);border-radius:15px;overflow:hidden;background:white;display:flex;flex-direction:column;box-shadow:0 5px 18px #22305d07;perspective:800px}.card-content{padding:18px 20px 20px;display:flex;flex-direction:column;flex:1}.card-meta{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:.8rem;color:var(--muted)}.category{color:#34478b;font-weight:700}.card h3{margin:7px 0 3px;font:600 1.6rem/1.3 Georgia,serif;letter-spacing:-.045em}.card p{margin:0 0 16px;color:var(--muted);font-size:.965rem;flex:1}.card button{align-self:flex-start;background:#edf0ff;color:#2d429d;font-size:.875rem}.card button:hover{background:#dfe5ff}\n.dash{margin:36px 0 20px}.dash h1{font-size:3rem}.dashboard-grid{margin-top:20px}.empty{padding:24px;background:#fff;border:1px dashed #b5c1d2;border-radius:12px;color:var(--muted)}footer{display:flex;gap:12px;align-items:center;border-top:1px solid var(--line);padding:22px 0;margin-top:48px;color:var(--muted);font-size:.85rem}footer span{font-weight:800;color:var(--ink)}\ndialog{width:min(540px,94vw);border:1px solid var(--line);border-radius:18px;max-height:88dvh;color:var(--ink);padding:24px;box-shadow:0 30px 80px #0d173955}dialog::backdrop{background:#101b37a8}.dialog-head{display:flex;gap:16px;justify-content:space-between;align-items:center}.dialog-head h2{font-size:2rem}.close{font-size:1.45rem;line-height:1;padding:.48rem .67rem}label{display:block;font-weight:650;margin:14px 0}input,select,textarea{display:block;margin-top:5px;border:1px solid #a9b5c8;padding:9px 11px;width:100%;border-radius:7px;color:var(--ink);background:#fff}textarea{resize:vertical}.tag,.feedback small{color:var(--muted)}.feedback,.stats{border-top:1px solid var(--line);padding-top:14px;margin-top:16px}.feedback p{margin:5px 0}.stats{font-weight:700}#message{color:#973015}#message:empty{display:none}\n@media(max-width:800px){.wrap{width:93%}.hero{padding:30px;grid-template-columns:1.15fr 1fr}.hero h1{font-size:3.5rem}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.header-inner{gap:1.5rem}}\n@media(max-width:600px){.header-inner{min-height:62px;gap:12px;flex-wrap:wrap;padding-block:10px}nav{gap:12px}nav a{font-size:.84rem}.brand{font-size:1.28rem;gap:6px}.brand-mark{width:26px;height:26px}.header-cta{font-size:.83rem;padding:.45rem .6rem}.hero{margin-top:15px;padding:28px 23px 12px;grid-template-columns:1fr}.hero h1{font-size:clamp(2.95rem,11.7vw,4rem)}.hero-copy>p:not(.kicker){font-size:.96rem}.flight-scene{width:min(84%,320px)!important;margin:-8px auto 0}.progress{gap:10px;padding:13px;margin-bottom:26px}.progress-icon{display:none}.segments i{width:15px}.progress-end{flex-direction:column;gap:4px}.grid{grid-template-columns:1fr}.directory-head{justify-content:space-between}.card-content{padding:16px}.filters{margin:14px 0}.kicker{margin-bottom:12px}}\n@media(max-width:410px){.header-inner{justify-content:space-between}.header-cta{order:1}nav{order:2;width:100%;padding-bottom:2px}.progress small{font-size:.8rem}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n.generic-cover{height:140px;background:linear-gradient(115deg,#dce3ff,#c0d5f3);display:grid;place-items:center}.generic-cover i{font:italic 58px/1 Georgia,serif;color:#2b427e;transform:rotate(-12deg);text-shadow:1px 2px #fff,2px 4px #9aaad9}\n@media(hover:hover) and (pointer:fine) and (prefers-reduced-motion:no-preference){.card .cover>div{transition:translate .3s,scale .3s}.card:hover .cover>div,.card:focus-within .cover>div{translate:0 -4px;scale:1.06}}\n\n.flight-scene {\n  position: relative;\n  align-self: center;\n  width: 100%;\n  max-width: 36rem;\n  aspect-ratio: 1.36;\n  container-type: inline-size;\n  isolation: isolate;\n  perspective: 850px;\n  pointer-events: none;\n  color: #dee9ff;\n}\n.flight-grid {\n  position: absolute;\n  inset: 0;\n  background-image: radial-gradient(circle, rgba(149,177,247,.52) .75px, transparent 1px);\n  background-size: 4.3% 5.85%;\n  mask-image: radial-gradient(ellipse at center, #000 25%, transparent 73%);\n}\n.flight-stage {\n  position: absolute;\n  inset: 0;\n  transform-style: preserve-3d;\n  transform: rotateX(var(--flight-rx, 0deg)) rotateY(var(--flight-ry, 0deg));\n  transition: transform .35s ease-out;\n}\n.flight-ring, .flight-orbit {\n  position: absolute;\n  border-radius: 50%;\n  pointer-events: none;\n}\n.flight-ring {\n  left: 7%;\n  top: 6%;\n  width: 85%;\n  height: 87%;\n  border: 1px dashed rgba(147,178,249,.5);\n  transform: rotate(-28deg) scaleY(.68);\n}\n.flight-ring-inner {\n  left: 13%;\n  top: 1%;\n  width: 76%;\n  height: 88%;\n  border-style: solid;\n  opacity: .4;\n  transform: rotate(24deg) scaleY(.67);\n}\n.flight-orbit {\n  left: 4%;\n  top: 28%;\n  width: 90%;\n  height: 45%;\n  border: 1px solid rgba(156,186,252,.35);\n  transform: rotate(-31deg);\n}\n.flight-orbit i {\n  position: absolute;\n  width: 5px;\n  height: 5px;\n  left: 15%;\n  top: 12%;\n  border-radius: 50%;\n  background: #e1edff;\n  box-shadow: 0 0 0 3px #ccd9ff22;\n}\n.flight-pack {\n  position: absolute;\n  left: 31%;\n  top: 29%;\n  width: 43%;\n  height: 40%;\n  transform: rotateX(16deg) rotateY(-24deg) rotateZ(-10deg);\n  transform-style: preserve-3d;\n  animation: flight-arrive .9s cubic-bezier(.22,.7,.23,1) both;\n}\n.flight-sheet {\n  position: absolute;\n  inset: 0;\n  border-radius: 6% / 8%;\n  border: 1px solid #edf3ff8c;\n}\n.flight-sheet-back {\n  background: linear-gradient(130deg,#4566d4,#27408e);\n  transform: translate3d(5%,16%,-12px) rotate(5deg);\n  box-shadow: .4cqw 2.5cqw 4.3cqw #060b2555;\n}\n.flight-sheet-mid {\n  background: linear-gradient(120deg,#d9e5ff 0%,#95b2f1 70%,#7497d6 100%);\n  transform: translate3d(3%,8%,-6px) rotate(2deg);\n  box-shadow: 0 .65cqw 0 #6e8dc4;\n}\n.flight-sheet-face {\n  padding: 8% 10%;\n  background: linear-gradient(145deg,#fffef5,#eaf0ff 80%);\n  box-shadow: inset 1px 1px 0 white, 0 .7cqw 0 #c1cbe0;\n}\n.flight-dots { display:flex; gap:3%; height:5%; align-items:center; }\n.flight-dots i { width:3%; aspect-ratio:1; border-radius:50%; background:#a4b4ce; }\n.flight-dots i:first-child { background:#fa8659; }\n.flight-stars { \n  color: #304997;\n  font-family: Arial,sans-serif;\n  font-weight: 800;\n  font-size: 3.8cqw;\n  line-height: 1.1;\n  letter-spacing: .15cqw;\n  margin: 10% 0 9%;\n  white-space: nowrap;\n}\n.flight-lines { display:grid; gap:1.05cqw; }\n.flight-lines i { width:91%; height:.9cqw; background:#c1cde3; border-radius:2px; }\n.flight-lines i:nth-child(2) { width:72%; }\n.flight-lines i:nth-child(3) { width:42%; background:#d0d9e9; }\n.flight-plane {\n  position: absolute;\n  aspect-ratio: 1.52;\n  filter: drop-shadow(.55cqw 1.4cqw 1.25cqw #080c2a55);\n}\n.flight-plane i { position:absolute; inset:0; }\n.flight-plane i:nth-child(1) {\n  clip-path: polygon(0 42%,100% 0%,40% 60%);\n  background: linear-gradient(115deg,var(--wing-light),var(--wing-main));\n}\n.flight-plane i:nth-child(2) {\n  clip-path: polygon(40% 60%,100% 0%,43% 94%);\n  background: linear-gradient(60deg,var(--wing-shadow),var(--wing-main));\n}\n.flight-plane i:nth-child(3) {\n  clip-path: polygon(43% 94%,51% 67%,100% 0%);\n  background: var(--wing-dark);\n}\n.flight-plane i:nth-child(4) {\n  clip-path: polygon(49% 65%,100% 0%,77% 95%);\n  background: linear-gradient(130deg,var(--wing-light),var(--wing-main) 68%,var(--wing-shadow));\n}\n.flight-plane-orange {\n  --wing-main:#ff965b; --wing-light:#ffe1ae; --wing-shadow:#e96336; --wing-dark:#97391f;\n  width:42%; top:4%; right:4%;\n  transform: translateZ(3.5cqw) rotate(4deg);\n}\n.flight-plane-blue {\n  --wing-main:#779bff; --wing-light:#d1dfff; --wing-shadow:#4568d0; --wing-dark:#253e88;\n  width:33%; bottom:7%; left:7%;\n  transform: translateZ(2.5cqw) rotate(162deg);\n}\n.flight-glint {\n  position:absolute; aspect-ratio:1; width:2.5%; background:#a8bdf0;\n  clip-path: polygon(50% 0,60% 41%,100% 50%,60% 59%,50% 100%,40% 59%,0 50%,40% 41%);\n}\n.flight-glint-one { top:23%; left:16%; }\n.flight-glint-two { bottom:21%; right:15%; width:1.8%; }\n@keyframes flight-arrive {\n  from { opacity:.3; transform: translateY(3%) rotateX(24deg) rotateY(-33deg) rotateZ(-13deg); }\n  to { opacity:1; transform: rotateX(16deg) rotateY(-24deg) rotateZ(-10deg); }\n}\n@media(prefers-reduced-motion:reduce){\n  .flight-pack { animation:none; }\n  .flight-stage { transform:none; transition:none; }\n}\n\n.cover.cv-scene {\n  height: 140px;\n  position: relative;\n  display: grid;\n  place-items: center;\n  isolation: isolate;\n  overflow: hidden;\n}\n.cv-ledger { background: radial-gradient(ellipse at 34% 0%, #edebff, transparent 70%), linear-gradient(120deg,#d2caff,#a598eb); }\n.cv-tiffin { background: radial-gradient(ellipse at 36% 0%,#ffead5,transparent 75%), linear-gradient(125deg,#ffcba8,#efae8f); }\n.cv-sheets { background: radial-gradient(ellipse at 33% 0%,#e2fcf0,transparent 70%),linear-gradient(125deg,#bcebdc,#91d9ca); }\n.cv-scene::before {\n  content: \"\"; position: absolute; inset: 0; z-index: -1;\n  background-image: linear-gradient(126deg, transparent 22%, #ffffff28 22.2%, transparent 22.8%, transparent 62%, #ffffff34 62.3%, transparent 62.8%);\n}\n.cv-book {\n  width: 82px; height: 103px; position: relative;\n  transform: perspective(380px) rotateX(38deg) rotateZ(-28deg) skewY(4deg);\n  border-radius: 4px 9px 8px 4px;\n  background: linear-gradient(95deg,#4e3fa9 0 8%,#9389f5 9%,#5751c6 12%,#8a7af3 15%,#6f64dd 62%,#564dbc);\n  border: 1px solid #7267cf;\n  box-shadow: 0 2px #383081,0 3px #eadff3,0 4px #aeaac8,0 5px #eee7f6,0 6px #aeaac8,0 7px #eee7f6,0 9px #5946a7,2px 18px 13px -4px #44399366;\n}\n.cv-book::after {\n  content:\"\";position:absolute;left:27%;top:22%;width:47%;height:27%;\n  background:repeating-linear-gradient(0deg,transparent 0 7px,#dcd7ff66 7px 8px),repeating-linear-gradient(90deg,transparent 0 11px,#dcd7ff66 11px 12px);\n  border:1px solid #dcd7ffaa;border-radius:2px;\n}\n.cv-strap {position:absolute;right:11%;inset-block:-1px;width:7px;background:linear-gradient(90deg,#2b226e,#4a3d9a 65%,#32286d);box-shadow:2px 1px 2px #30246566;}\n.cv-stack {position:relative;width:91px;height:103px;transform:rotate(-8deg);filter:drop-shadow(3px 10px 5px #ab643b55);}\n.cv-bowl {\n  position:absolute;left:5px;width:80px;height:27px;border-radius:48% 48% 35% 36% / 20% 20% 34% 34%;\n  background:linear-gradient(90deg,#a94633,#e97953 15%,#ffb087 34%,#ff8f6e 62%,#df694e 82%,#a54a36);\n  border-bottom:3px solid #983f30;box-shadow:inset 0 3px 0 #ffc2a3,inset 0 -4px 0 #d36348;\n}\n.cv-bowl:nth-child(1){bottom:5px}.cv-bowl:nth-child(2){bottom:26px}.cv-bowl:nth-child(3){bottom:47px}\n.cv-lid {position:absolute;left:2px;bottom:65px;width:86px;height:18px;border-radius:50%;background:radial-gradient(ellipse at 40% 28%,#ffba91 8%,#ec8765 57%,#b85840 69%,#ffbd9b 76%);box-shadow:0 3px 0 #9c4937;}\n.cv-handle {position:absolute;left:32px;bottom:75px;width:29px;height:17px;border:4px solid #7e5041;border-bottom:0;border-radius:12px 12px 2px 2px;box-shadow:inset 2px 1px #f5c8a8,2px -1px #ffcaab;}\n.cv-clasp {position:absolute;bottom:22px;right:15px;width:6px;height:46px;border-radius:4px;background:linear-gradient(90deg,#905d4a,#f9d4ab 42%,#b27f67 82%);box-shadow:1px 2px 2px #914c3d;}\n.cv-paper {width:83px;height:98px;position:relative;transform:perspective(370px) rotateX(44deg) rotateZ(-29deg) skewY(3deg);}\n.cv-leaf {\n  position:absolute;inset:0;border-radius:3px;\n  box-shadow:1px 2px 0 #6fa89a,2px 8px 10px -6px #245b4b77;\n}\n.cv-leaf:nth-child(1){background:#599f91;transform:translate(-6px,10px) rotate(-11deg);box-shadow:2px 11px 9px #32766355}\n.cv-leaf:nth-child(2){background:#d2ede2;transform:translate(-2px,6px) rotate(-6deg);}\n.cv-leaf:nth-child(3){background:linear-gradient(140deg,#fff,#edfaf3 75%);border:1px solid #ccded4;}\n.cv-leaf:nth-child(3)::before {content:\"\";position:absolute;left:13px;top:17px;width:20px;height:7px;border-radius:2px;background:#317a66;}\n.cv-leaf:nth-child(3)::after {content:\"\";position:absolute;inset:33px 13px 18px;background:repeating-linear-gradient(180deg,#a6cec0 0 2px,transparent 2px 9px);clip-path:polygon(0 0,100% 0,100% 65%,73% 65%,73% 100%,0 100%);}\n</style>\n</head>\n<body>\n<header class=\"site-header\"><div class=\"wrap header-inner\">\n<a class=\"brand\" href=\"#discover\" aria-label=\"PitchAdda home\"><span class=\"brand-mark\" aria-hidden=\"true\"><i></i><i></i><i></i></span>PitchAdda</a>\n<nav aria-label=\"Main navigation\"><a href=\"#discover\">Discover</a><a href=\"#dashboard\">Dashboard</a></nav>\n<button class=\"header-cta\" data-list><b aria-hidden=\"true\">+</b> List a product</button>\n</div></header>\n<main class=\"wrap\" id=\"page\"><p role=\"status\">Loading exchange…</p></main>\n<footer class=\"wrap\"><span>PitchAdda</span> Founder feedback exchange</footer>\n<dialog aria-labelledby=\"dialog-title\" id=\"modal\"><div class=\"dialog-head\"><h2 id=\"dialog-title\"></h2><button class=\"close\" aria-label=\"Close dialog\" onclick=\"modal.close()\">×</button></div><div id=\"dialog-content\"></div><p id=\"message\" role=\"status\"></p></dialog>\n<template id=\"flight\"><div class=\"flight-scene\" aria-hidden=\"true\">\n  <div class=\"flight-grid\"></div>\n  <div class=\"flight-stage\">\n    <div class=\"flight-ring flight-ring-outer\"></div>\n    <div class=\"flight-ring flight-ring-inner\"></div>\n    <div class=\"flight-orbit\"><i></i></div>\n    <div class=\"flight-pack\">\n      <div class=\"flight-sheet flight-sheet-back\"></div>\n      <div class=\"flight-sheet flight-sheet-mid\"></div>\n      <div class=\"flight-sheet flight-sheet-face\">\n        <div class=\"flight-dots\"><i></i><i></i><i></i></div>\n        <div class=\"flight-stars\">★★★★★</div>\n        <div class=\"flight-lines\"><i></i><i></i><i></i></div>\n      </div>\n    </div>\n    <div class=\"flight-plane flight-plane-blue\"><i></i><i></i><i></i><i></i></div>\n    <div class=\"flight-plane flight-plane-orange\"><i></i><i></i><i></i><i></i></div>\n    <span class=\"flight-glint flight-glint-one\"></span>\n    <span class=\"flight-glint flight-glint-two\"></span>\n  </div>\n</div>\n</template>\n<template id=\"covers\"><div class=\"cover cv-scene cv-ledger\" aria-hidden=\"true\"><div class=\"cv-book\"><span class=\"cv-strap\"></span></div></div>\n<div class=\"cover cv-scene cv-tiffin\" aria-hidden=\"true\"><div class=\"cv-stack\"><span class=\"cv-bowl\"></span><span class=\"cv-bowl\"></span><span class=\"cv-bowl\"></span><span class=\"cv-lid\"></span><span class=\"cv-handle\"></span><span class=\"cv-clasp\"></span></div></div>\n<div class=\"cover cv-scene cv-sheets\" aria-hidden=\"true\"><div class=\"cv-paper\"><span class=\"cv-leaf\"></span><span class=\"cv-leaf\"></span><span class=\"cv-leaf\"></span></div></div></template>\n<script>const page = document.querySelector('#page');\nconst modal = document.querySelector('#modal');\nconst message = document.querySelector('#message');\nconst covers = [...document.querySelector('#covers').content.children];\nconst flight = document.querySelector('#flight').innerHTML;\nlet state;\nlet category = '';\nconst esc = value => String(value ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '\"':'&quot;', \"'\":'&#39;'}[c]));\nconst dashboard = () => location.hash === '#dashboard';\nasync function sync() {\n  const response = await fetch('/api');\n  if (!response.ok) throw Error('The exchange could not load. Please refresh.');\n  state = await response.json();\n  render();\n}\nfunction card(p) {\n  const art = p.seed ? covers[p.id - 1] : null;\n  const image = art?.outerHTML ?? `<div class=\"generic-cover\" aria-hidden=\"true\"><i>${esc(p.name.slice(0, 1))}</i></div>`;\n  return `<article class=\"card\">${image}<div class=\"card-content\">\n    <div class=\"card-meta\"><span class=\"category\">${esc(p.category)}</span>${p.seed ? 'Practice brief' : ''}</div>\n    <h3>${esc(p.name)}</h3><p>${esc(p.description)}</p>\n    <button data-product=\"${p.id}\">${p.mine ? 'View feedback' : p.done ? 'View product' : 'Review product'}</button></div></article>`;\n}\nfunction progress() {\n  const count = Math.min(3, state.count);\n  return `<section class=\"progress\" aria-label=\"Listing eligibility\">\n    <span class=\"progress-icon\" aria-hidden=\"true\">✦</span><div><strong>${count === 3 ? 'Your listing is unlocked' : 'Unlock your product listing'}</strong>\n    <small>${count === 3 ? 'Add your product and questions for reviewers.' : 'Review three different products to share your own.'}</small></div>\n    <div class=\"progress-end\"><span>${count} / 3 reviews</span><span class=\"segments\" aria-hidden=\"true\">${[0,1,2].map(i => `<i class=\"${i<count?'on':''}\"></i>`).join('')}</span></div></section>`;\n}\nfunction render() {\n  if (!state) return;\n  const mine = dashboard();\n  document.querySelectorAll('nav a').forEach(a => {\n    if (a.hash === (mine ? '#dashboard' : '#discover')) a.setAttribute('aria-current','page');\n    else a.removeAttribute('aria-current');\n  });\n  const categories = ['', ...new Set(state.products.map(p => p.category))];\n  const list = state.products.filter(p => mine ? p.mine : !category || p.category === category);\n  const hero = `<section class=\"hero\"><div class=\"hero-copy\"><p class=\"kicker\">FOUNDER FEEDBACK EXCHANGE</p>\n    <h1>Your next idea,<br><em>peer reviewed.</em></h1>\n    <p>Get fresh eyes on your product from India’s founder community. Start by giving feedback of your own.</p>\n    <a class=\"hero-button\" href=\"#directory\">Explore products</a></div>${flight}</section>`;\n  page.innerHTML = (mine ? '<section class=\"dash\"><h1>Founder dashboard</h1></section>' : hero) + progress() +\n    `<section id=\"directory\"><div class=\"directory-head\"><h2>${mine?'Your products':'Product directory'}</h2>\n    <span>${list.length} ${list.length===1?'product':'products'}</span></div>` +\n    (mine ? '' : `<div class=\"filters\" role=\"group\" aria-label=\"Filter products by category\">${categories.map((c,i)=>\n      `<button data-category=\"${i}\" aria-pressed=\"${category===c}\">${esc(c || 'All products')}</button>`).join('')}</div>`) +\n    `<div class=\"grid ${mine?'dashboard-grid':''}\">${list.map(card).join('')}</div>` +\n    (list.length ? '' : '<p class=\"empty\">Your listings and their feedback will appear here.</p>') + '</section>';\n}\nfunction openBox(title, body) {\n  document.querySelector('#dialog-title').textContent = title;\n  document.querySelector('#dialog-content').innerHTML = body;\n  message.textContent = '';\n  if (!modal.open) modal.showModal();\n}\nfunction field(name, label, type='text', max=300) {\n  return `<label>${esc(label)}<input required name=\"${name}\" type=\"${type}\" maxlength=\"${max}\"></label>`;\n}\nfunction listing() {\n  if (!state) return;\n  if (state.count < 3) {\n    const left = 3 - state.count;\n    openBox('Unlock your listing', `<p>Review ${left} more ${left===1?'product':'products'} to publish your own brief.</p><button class=\"primary\" data-explore>Explore products</button>`);\n    return;\n  }\n  openBox('List your product', `<form data-action=\"list\">${field('name','Product name','text',80)}${field('url','Website URL','url')}\n    ${field('category','Category','text',40)}${field('description','One-line description')}${field('q1','First question for reviewers')}${field('q2','Second question for reviewers')}\n    <label>Third question (optional)<input name=\"q3\" maxlength=\"300\"></label><button class=\"primary\">Publish listing</button></form>`);\n}\nfunction detail(id) {\n  const p = state.products.find(product => product.id === id);\n  if (!p) return;\n  const introduction = `<p>${esc(p.description)}</p>` + (p.url ? `<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"${esc(p.url)}\">Visit product website</a>` : '<p class=\"tag\">Practice brief · Review the concept described above.</p>');\n  if (p.mine) {\n    const comments = p.feedback.map(f => `<div class=\"feedback\"><strong>${esc(f.note)}</strong><p><small>${esc(f.rating)} / 5 · ${esc(f.intent)}</small></p>\n      ${JSON.parse(f.answers).map((answer,i) => `<p><b>${esc(p.questions[i])}</b><br>${esc(answer)}</p>`).join('')}</div>`).join('');\n    openBox(p.name, introduction + `<div class=\"stats\">${p.total} reviews · ${p.avg??'—'} / 5 · ${p.waits} on waitlist</div>${comments}`);\n    return;\n  }\n  openBox(p.name, introduction + `<p><button data-join=\"${id}\" ${p.joined?'disabled':''}>${p.joined?'Joined waitlist':'Join waitlist'}</button></p>` +\n    (p.done ? '<p>Your review has been recorded.</p>' :\n    `<form data-action=\"review\" data-id=\"${id}\">${p.questions.map((q,i) => field('a'+i,q)).join('')}\n    <label>Overall rating<select name=\"rating\">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></label>${field('note','One-line feedback')}\n    <label>Would you use it?<select name=\"intent\"><option>Would use</option><option>Would pay</option><option>Would pass</option></select></label>\n    <button class=\"primary\">Submit review</button></form>`));\n}\nasync function post(payload) {\n  const response = await fetch('/api', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(payload)});\n  if (!response.ok) throw Error(await response.text());\n  await sync();\n}\ndocument.addEventListener('click', async event => {\n  const button = event.target.closest('button');\n  if (!button) return;\n  if (button.hasAttribute('data-list')) return listing();\n  if (button.hasAttribute('data-product')) return detail(Number(button.dataset.product));\n  if (button.hasAttribute('data-category')) {\n    category = ['', ...new Set(state.products.map(p=>p.category))][Number(button.dataset.category)];\n    render();\n    page.querySelector(`[data-category=\"${button.dataset.category}\"]`).focus({preventScroll:true});\n  }\n  if (button.hasAttribute('data-explore')) {\n    modal.close();\n    location.hash='directory';\n    render();\n    document.querySelector('#directory').scrollIntoView();\n  }\n  if (button.hasAttribute('data-join')) {\n    const id = Number(button.dataset.join);\n    button.disabled = true;\n    try { await post({action:'join',id}); detail(id); }\n    catch(error) { message.textContent = error.message; button.disabled = false; }\n  }\n});\nmodal.addEventListener('submit',async event => {\n  event.preventDefault();\n  const form=event.target;\n  const action=form.dataset.action;\n  const button=form.querySelector('button');\n  button.disabled=true;\n  try {\n    await post({...Object.fromEntries(new FormData(form)),action,id:Number(form.dataset.id)});\n    modal.close();\n    if (action==='list') location.hash='dashboard';\n    else detail(Number(form.dataset.id));\n  } catch(error) { message.textContent=error.message; button.disabled=false; }\n});\nwindow.addEventListener('hashchange', () => {\n  render();\n  if (location.hash==='#directory') document.querySelector('#directory')?.scrollIntoView();\n  else window.scrollTo(0,0);\n});\nconst motion = matchMedia('(prefers-reduced-motion: no-preference) and (hover: hover) and (pointer: fine)');\npage.addEventListener('pointermove', event => {\n  if (!motion.matches) return;\n  const hero = event.target.closest('.hero');\n  if (!hero) return;\n  const rect = hero.getBoundingClientRect();\n  hero.style.setProperty('--flight-ry', ((event.clientX-rect.left)/rect.width*16-8)+'deg');\n  hero.style.setProperty('--flight-rx', (6-(event.clientY-rect.top)/rect.height*12)+'deg');\n});\npage.addEventListener('pointerout', event => {\n  const hero = event.target.closest('.hero');\n  if (hero && !hero.contains(event.relatedTarget)) {\n    hero.style.removeProperty('--flight-rx'); hero.style.removeProperty('--flight-ry');\n  }\n});\nsync().catch(error=>page.textContent=error.message);\n</script>\n</body></html>\n";
const seeds=[
 ['KhataKit','Fintech','A pocket ledger that reminds independent shopkeepers which invoices are overdue.'],
 ['Tiffin Club','Food & drink','Discover weekly lunch subscriptions from home cooks near your office.'],
 ['SprintPatra','Productivity','Turn a small team’s weekly updates into a single digest for busy founders.']
];
const questions=['Who would benefit most from this idea?','What would you need to know before trying it?'];
async function setup(db){
 await db.batch([
 'CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, owner TEXT, name TEXT, category TEXT, description TEXT, url TEXT, questions TEXT)',
 'CREATE TABLE IF NOT EXISTS reviews(product INTEGER, person TEXT, rating INTEGER, note TEXT, intent TEXT, answers TEXT, PRIMARY KEY(product,person))',
 'CREATE TABLE IF NOT EXISTS waits(product INTEGER,person TEXT,PRIMARY KEY(product,person))'
 ].map(q=>db.prepare(q)).concat(seeds.map((s,i)=>db.prepare('INSERT OR IGNORE INTO products VALUES(?,NULL,?,?,?,NULL,?)').bind(i+1,...s,JSON.stringify(questions)))))
}
export default {async fetch(req,env){
 const url=new URL(req.url);
 if(url.pathname==='/')return new Response(PAGE,{headers:{'Content-Type':'text/html;charset=utf-8'}});
 if(url.pathname!='/api')return new Response('Missing page',{status:404});
 const db=env.DB,user=req.headers.get('oai-authenticated-user-id');
 const fail=(s,status=400)=>new Response(s,{status});
 await setup(db);
 const count=async()=>Number(await db.prepare('SELECT COUNT(*) FROM reviews WHERE person=?').bind(user||'').first('COUNT(*)'));
 if(req.method==='GET'){
 const {results}=await db.prepare(`SELECT p.*, (SELECT count(*) FROM reviews WHERE product=p.id) total,(SELECT round(avg(rating),1) FROM reviews WHERE product=p.id) avg,(SELECT count(*) FROM waits WHERE product=p.id) waits, EXISTS(SELECT 1 FROM reviews WHERE product=p.id AND person=?1) done, EXISTS(SELECT 1 FROM waits WHERE product=p.id AND person=?1) joined FROM products p ORDER BY owner IS NULL, CASE WHEN owner IS NULL THEN id ELSE -id END`).bind(user||'').all();
 const products=await Promise.all(results.map(async({owner,...p})=>({...p,questions:JSON.parse(p.questions),mine:!!user&&owner===user,seed:owner===null,feedback:user&&owner===user?(await db.prepare('SELECT note,rating,intent,answers FROM reviews WHERE product=? ORDER BY rowid DESC').bind(p.id).all()).results:[]})));
 return Response.json({products,count:await count()},{headers:{'Cache-Control':'private, no-store'}})}
 if(req.method!=='POST')return fail('Unsupported method',405);
 if(!user)return fail('Sign in to participate.',401);
 if(req.headers.get('Origin')!==url.origin)return fail('Invalid origin',403);
 let b;try{b=await req.json()}catch{return fail('Invalid request')}
 const valid=(v,n=300)=>typeof v==='string'&&v.trim().length>0&&v.length<=n;
 if(b.action==='list'){
 if(await count()<3)return fail('Complete three reviews first.',403);
 if(!valid(b.name,80)||!valid(b.category,40)||![b.description,b.url,b.q1,b.q2].every(v=>valid(v))||(b.q3&&!valid(b.q3)))return fail('Complete each required field.');
 let link;try{link=new URL(b.url)}catch{return fail('Enter a valid website URL.')}if(!['https:','http:'].includes(link.protocol))return fail('Use an HTTP or HTTPS website.');
 await db.prepare('INSERT INTO products(owner,name,category,description,url,questions) VALUES(?,?,?,?,?,?)').bind(user,b.name,b.category,b.description,link.href,JSON.stringify([b.q1,b.q2,b.q3].filter(Boolean))).run()
 }else{
 const p=await db.prepare('SELECT owner,questions FROM products WHERE id=?').bind(Number(b.id)||0).first();
 if(!p||p.owner===user)return fail('Choose another founder’s product.');
 if(b.action==='join')await db.prepare('INSERT OR IGNORE INTO waits VALUES(?,?)').bind(b.id,user).run();
 else if(b.action==='review'){const answers=JSON.parse(p.questions).map((_,i)=>b['a'+i]);if(!answers.every(v=>valid(v))||!valid(b.note)||!['Would use','Would pay','Would pass'].includes(b.intent)||!['1','2','3','4','5'].includes(String(b.rating)))return fail('Complete the review.');
 await db.prepare('INSERT OR IGNORE INTO reviews VALUES(?,?,?,?,?,?)').bind(b.id,user,Number(b.rating),b.note,b.intent,JSON.stringify(answers)).run()
 }else return fail('Unknown action')}
 return Response.json({saved:true})
}};
